391:     let mut out = Out { w, cd: Vec::new(), count: 0, offset: 0, password, level };
392:     let mut items: Vec<(Location, String)> = vec![];
393:     fn walk(reg: &Registry, l: &Location, name: String, out: &mut Vec<(Location, String)>) {
394:         let Some(v) = reg.get(&l.fs) else { return };
395:         if let Ok(e) = v.stat(&l.path) {
396:             if e.is_dir {
397:                 if let Ok(list) = v.list(&l.path) {
398:                     for c in list.into_iter().filter(|c| !c.symlink) {
399:                         walk(reg, &c.loc, format!("{}/{}", name, c.name), out);
400:                     }
401:                 }
402:             } else {
403:                 out.push((l.clone(), name));
404:             }
405:         }
406:     }
407:     for s in srcs {
408:         let Some(v) = reg.get(&s.fs) else { continue };
409:         let Ok(e) = v.stat(&s.path) else { continue };
410:         walk(reg, s, e.name.clone(), &mut items);
411:     }
412:     let total: u64 = items.len() as u64;
413:     let mut n = 0usize;
414:     for (l, name) in items {
415:         out.file(reg, &l, &name)?;
416:         n += 1;
417:         progress(&name, n as u64, total.max(1));
418:     }
419:     out.finish()?;
420:     Ok((n, total))
421: }
