466: // ───────────────────────────────── CLI fallback (7z · rar · tar · xz) ─────────────────────────────────
467: // The native ZIP engine above is dependency-free; everything else shells out to the best
468: // available tool so "browse" and "extract" keep working, with real progress where possible.
469: 
470: #[cfg(not(target_arch = "wasm32"))]
471: fn lower_ext(p: &std::path::Path) -> String {
472:     let n = p.file_name().map(|n| n.to_string_lossy().to_lowercase()).unwrap_or_default();
473:     for suf in [".tar.gz", ".tar.xz", ".tar.bz2", ".tar.zst"] {
474:         if n.ends_with(suf) {
475:             return suf.to_string();
476:         }
477:     }
478:     p.extension().map(|e| format!(".{}", e.to_string_lossy().to_lowercase())).unwrap_or_default()
479: }
480: 
481: #[cfg(not(target_arch = "wasm32"))]
482: fn run_lines(bin: &str, args: &[&str]) -> Option<Vec<String>> {
483:     let out = std::process::Command::new(bin).args(args).output().ok()?;
484:     if !out.status.success() && out.stdout.is_empty() {
485:         return None;
486:     }
487:     Some(String::from_utf8_lossy(&out.stdout).lines().map(|s| s.to_string()).collect())
488: }
489: 
490: #[cfg(not(target_arch = "wasm32"))]
491: fn which(bins: &[&str]) -> Option<&'static str> {
492:     for b in bins {
493:         if std::process::Command::new("sh").args(["-c", &format!("command -v {b}")]).output().map(|o| o.status.success()).unwrap_or(false) {
494:             return Some(b);
495:         }
496:     }
497:     None
498: }
499: 
500: /// List entries of any common archive via system tools. Returns `None` when no tool applies.
501: #[cfg(not(target_arch = "wasm32"))]
502: pub fn cli_list(real: &std::path::Path) -> Option<Vec<ZipEntry>> {
503:     let ext = lower_ext(real);
504:     let s = real.to_string_lossy();
505:     let lines: Vec<String> = if matches!(ext.as_str(), ".7z" | ".rar") {
506:         return None; // 7z listing parsing is brittle; extraction still works below
507:     } else if let Some(bsdtar) = which(&["bsdtar"]) {
508:         run_lines(bsdtar, &["-tf", &s])?
509:     } else if matches!(ext.as_str(), ".tar" | ".tar.gz" | ".tgz" | ".tar.xz" | ".txz" | ".tar.bz2" | ".tbz2") {
510:         run_lines("tar", &["-tf", &s])?
511:     } else if matches!(ext.as_str(), ".zip") {
512:         run_lines("unzip", &["-Z", "-1", &s])?
513:     } else {
514:         return None;
515:     };
516:     let mut v = vec![];
517:     for l in lines {
518:         let name = l.trim().trim_start_matches("./").to_string();
519:         if name.is_empty() {
520:             continue;
521:         }
522:         v.push(ZipEntry { name: name.clone(), is_dir: name.ends_with('/'), size: 0, compressed: 0, encrypted: false, method: 0 });
523:     }
524:     Some(v)
525: }
526: 
527: /// Extract any common archive via system tools, emitting one progress step per line.
528: #[cfg(not(target_arch = "wasm32"))]
529: pub fn cli_extract(real: &std::path::Path, dest: &std::path::Path, total_hint: u64, mut progress: impl FnMut(&str, u64, u64)) -> Option<R<(usize, u64)>> {
530:     use std::io::{BufRead, BufReader};
531:     use std::process::Stdio;
532:     let ext = lower_ext(real);
533:     let s = real.to_string_lossy().to_string();
534:     let d = dest.to_string_lossy().to_string();
535:     let (bin, args): (&str, Vec<String>) = if ext == ".7z" || ext == ".rar" {
536:         ("7z", vec!["x".into(), "-y".into(), format!("-o{d}"), s.clone()])
537:     } else if let Some(b) = which(&["bsdtar"]) {
538:         (b, vec!["-x".into(), "-f".into(), s.clone(), "-C".into(), d.clone(), "-v".into()])
539:     } else if matches!(ext.as_str(), ".tar" | ".tar.gz" | ".tgz" | ".tar.xz" | ".txz" | ".tar.bz2" | ".tbz2") {
540:         ("tar", vec!["-x".into(), "-f".into(), s.clone(), "-C".into(), d.clone(), "-v".into()])
541:     } else if ext == ".zip" {
542:         ("unzip", vec!["-o".into(), "-d".into(), d.clone(), s.clone()])
543:     } else {
544:         return None;
545:     };
546:     let mut child = std::process::Command::new(bin).args(&args).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().ok()?;
547:     let stdout = child.stdout.take()?;
548:     let mut done = 0u64;
549:     let mut files = 0usize;
550:     let total = total_hint.max(1);
551:     for line in BufReader::new(stdout).lines().map_while(Result::ok) {
552:         let name = line.trim().trim_start_matches("x ").trim_start_matches("./").to_string();
553:         if !name.is_empty() {
554:             done += 1;
555:             files += 1;
556:             progress(&name, done.min(total), total);
557:         }
558:     }
559:     let ok = child.wait().map(|s| s.success()).unwrap_or(false);
560:     if ok {
561:         progress("", total, total);
562:         Some(Ok((files, done)))
563:     } else {
564:         Some(Err(ZipError::Io(format!("{bin} failed"))) )
565:     }
566: }

